def clean_mask(mask, iters=1):
    from scipy import ndimage as ndi
    mask = mask.astype(bool)
    mask = ndi.binary_opening(mask, iterations=iters)
    mask = ndi.binary_closing(mask, iterations=iters)
    return mask.astype(np.uint8)

def make_weighted_ce(labels, num_classes, device):
    counts = torch.bincount(torch.as_tensor(labels), minlength=num_classes).float()
    weights = counts.sum() / counts.clamp(min=1)
    weights = weights / weights.mean()
    return torch.nn.CrossEntropyLoss(weight=weights.to(device))

def ensemble_predict(logits_list):
    probs = [torch.softmax(logits, dim=1) for logits in logits_list]
    mean_prob = torch.stack(probs).mean(dim=0)
    return mean_prob.argmax(dim=1)

def blend_candidates(frames):
    df = pd.concat(frames, ignore_index=True)
    src = df.groupby(['user_id', 'item_id'])['source'].agg(lambda x: '|'.join(sorted(set(x)))).rename('sources')
    df = df.drop_duplicates(['user_id', 'item_id']).drop(columns=['source']).reset_index(drop=True)
    return df.join(src, on=['user_id', 'item_id'])

def topk_per_user(candidates, k=10):
    df = candidates.sort_values(['user_id', 'score'], ascending=[True, False])
    df = df.groupby('user_id').head(k)
    return df[['user_id', 'item_id', 'score']].reset_index(drop=True)

def add_recency(candidates, interactions, cutoff_ts, tau):
    last_ts = interactions.groupby(['user_id', 'item_id'])['ts'].max().rename('last_ts')
    out = candidates.join(last_ts, on=['user_id', 'item_id'])
    age = cutoff_ts - out['last_ts']
    out['ui_recency'] = np.exp(-age / tau).fillna(0.0)
    return out.drop(columns=['last_ts'])

def smooth_ce(logits, target, eps=0.1):
    log_prob = torch.log_softmax(logits, dim=1)
    nll = -log_prob.gather(1, target[:, None]).squeeze(1)
    smooth = -log_prob.mean(dim=1)
    return ((1 - eps) * nll + eps * smooth).mean()
